const clock = new THREE.Clock();

// High quality renderer configuration
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Light neutral background for readability
scene.background = new THREE.Color(0xf0f4f8);
scene.fog = new THREE.Fog(0xf0f4f8, 10, 30);

// Cinematic three-point lighting setup
const keyLight = new THREE.DirectionalLight(0xfff8f0, 2.0);
keyLight.position.set(8, 12, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 40;
keyLight.shadow.camera.left = -12;
keyLight.shadow.camera.right = 12;
keyLight.shadow.camera.top = 12;
keyLight.shadow.camera.bottom = -12;
keyLight.shadow.bias = -0.0005;

const fillLight = new THREE.DirectionalLight(0xddeeff, 0.7);
fillLight.position.set(-8, 6, 6);

const rimLight = new THREE.PointLight(0x88ccff, 0.9, 25);
rimLight.position.set(0, 8, -8);

const ambientLight = new THREE.AmbientLight(0x505560, 0.5);
scene.add(ambientLight, keyLight, fillLight, rimLight);

// Reflective ground plane
const floorGeo = new THREE.PlaneGeometry(40, 40);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0xe8ecf1,
  roughness: 0.6,
  metalness: 0.3,
  envMapIntensity: 0.8
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -3;
floor.receiveShadow = true;
scene.add(floor);

// Magnet assembly group
const magnetGroup = new THREE.Group();
scene.add(magnetGroup);

// U-shaped Super Magnet (Horseshoe)
const magnetRadius = 2.2;
const magnetTube = 0.5;
const torusGeo = new THREE.TorusGeometry(magnetRadius, magnetTube, 16, 64, Math.PI);
const magnetBodyMat = new THREE.MeshPhysicalMaterial({
  color: 0x888899,
  metalness: 0.95,
  roughness: 0.2,
  clearcoat: 0.8,
  clearcoatRoughness: 0.1
});
const magnetBody = new THREE.Mesh(torusGeo, magnetBodyMat);
magnetBody.castShadow = true;
magnetBody.receiveShadow = true;
magnetGroup.add(magnetBody);

// North Pole (Blue) - Left
const poleGeo = new THREE.CylinderGeometry(magnetTube, magnetTube, 2.8, 32);
const northMat = new THREE.MeshPhysicalMaterial({
  color: 0x0066ff,
  metalness: 0.7,
  roughness: 0.3,
  emissive: 0x0044cc,
  emissiveIntensity: 0.4,
  clearcoat: 0.5
});
const northPole = new THREE.Mesh(poleGeo, northMat);
northPole.position.set(-magnetRadius, -1.8, 0);
northPole.castShadow = true;
magnetGroup.add(northPole);

// South Pole (Red) - Right
const southMat = new THREE.MeshPhysicalMaterial({
  color: 0xff3333,
  metalness: 0.7,
  roughness: 0.3,
  emissive: 0xcc2222,
  emissiveIntensity: 0.4,
  clearcoat: 0.5
});
const southPole = new THREE.Mesh(poleGeo, southMat);
southPole.position.set(magnetRadius, -1.8, 0);
southPole.castShadow = true;
magnetGroup.add(southPole);

// Magnetic Field Lines Visualization
const fieldGroup = new THREE.Group();
magnetGroup.add(fieldGroup);

const fieldLines = [];
const fieldParticles = [];

// Generate magnetic field lines (dipole field approximation)
for (let i = 0; i < 16; i++) {
  const offset = (i / 15) * 2 - 1; // -1 to 1
  const scale = 1 + Math.abs(offset) * 0.8;

  const curvePoints = [];
  const segments = 64;
  for (let j = 0; j <= segments; j++) {
    const t = j / segments;
    const angle = t * Math.PI;
    // Magnetic field line curve
    const x = Math.cos(angle) * (magnetRadius + 0.6) * scale;
    const y = Math.sin(angle) * 3.5 * scale + offset * 0.6;
    const z = offset * 1.5 * Math.sin(t * Math.PI);
    curvePoints.push(new THREE.Vector3(x, y, z));
  }

  const curve = new THREE.CatmullRomCurve3(curvePoints);
  const tubeGeo = new THREE.TubeGeometry(curve, 64, 0.025, 8, false);
  const tubeMat = new THREE.MeshPhysicalMaterial({
    color: 0x66aaff,
    metalness: 0.2,
    roughness: 0.1,
    transmission: 0.5,
    transparent: true,
    opacity: 0.35,
    emissive: 0x4488ff,
    emissiveIntensity: 0.6,
    side: THREE.DoubleSide
  });
  const tube = new THREE.Mesh(tubeGeo, tubeMat);
  fieldGroup.add(tube);
  fieldLines.push({ mesh: tube, baseOffset: offset, curve: curve });

  // Energy particles flowing along field lines
  const particleCount = 6;
  for (let k = 0; k < particleCount; k++) {
    const pGeo = new THREE.SphereGeometry(0.08, 16, 16);
    const pMat = new THREE.MeshStandardMaterial({
      color: 0xaaddff,
      metalness: 0.9,
      roughness: 0.1,
      emissive: 0x66aaff,
      emissiveIntensity: 0.8
    });
    const particle = new THREE.Mesh(pGeo, pMat);
    fieldGroup.add(particle);
    fieldParticles.push({
      mesh: particle,
      curve: curve,
      t: k / particleCount,
      speed: 0.15 + Math.random() * 0.1,
      offset: offset
    });
  }
}

// Iron filings / Metallic particles attracted to field
const filingsCount = 500;
const filingsGeo = new THREE.BufferGeometry();
const filingsPositions = new Float32Array(filingsCount * 3);
const filingsVelocities = [];

for (let i = 0; i < filingsCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const r = 4 + Math.random() * 5;
  const y = (Math.random() - 0.5) * 8;

  filingsPositions[i * 3] = r * Math.cos(theta);
  filingsPositions[i * 3 + 1] = y;
  filingsPositions[i * 3 + 2] = r * Math.sin(theta);

  filingsVelocities.push({
    x: 0, y: 0, z: 0,
    speed: 0.5 + Math.random() * 0.5
  });
}

filingsGeo.setAttribute('position', new THREE.BufferAttribute(filingsPositions, 3));
const filingsMat = new THREE.PointsMaterial({
  color: 0x667788,
  size: 0.1,
  transparent: true,
  opacity: 0.9,
  sizeAttenuation: true
});
const filings = new THREE.Points(filingsGeo, filingsMat);
magnetGroup.add(filings);

// Super magnetism energy core
const coreGeo = new THREE.IcosahedronGeometry(0.6, 2);
const coreMat = new THREE.MeshBasicMaterial({
  color: 0x88ccff,
  transparent: true,
  opacity: 0.4,
  wireframe: true
});
const core = new THREE.Mesh(coreGeo, coreMat);
core.position.y = 1.2;
magnetGroup.add(core);

const innerCoreGeo = new THREE.SphereGeometry(0.3, 32, 32);
const innerCoreMat = new THREE.MeshBasicMaterial({
  color: 0xccffff,
  transparent: true,
  opacity: 0.6
});
const innerCore = new THREE.Mesh(innerCoreGeo, innerCoreMat);
innerCore.position.y = 1.2;
magnetGroup.add(innerCore);

// Environment map generation for PBR reflections
const cubeRenderTarget = new THREE.WebGLCubeRenderTarget(512);
const cubeCamera = new THREE.CubeCamera(0.1, 1000, cubeRenderTarget);
scene.add(cubeCamera);

// Update environment map once after scene setup
setTimeout(() => {
  cubeCamera.update(renderer, scene);
  scene.environment = cubeRenderTarget.texture;
}, 50);

// Camera and controls setup
camera.position.set(7, 5, 9);
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 0.5, 0);
controls.minDistance = 5;
controls.maxDistance = 20;
controls.maxPolarAngle = Math.PI / 2 - 0.05;
controls.update();

// Animation loop
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  // Levitation and rotation of magnet
  magnetGroup.position.y = Math.sin(t * 0.8) * 0.3;
  magnetGroup.rotation.y = Math.sin(t * 0.15) * 0.3;

  // Animate field lines (pulsing energy)
  fieldLines.forEach((line, idx) => {
    const pulse = 0.3 + Math.sin(t * 3 + idx * 0.4) * 0.15;
    line.mesh.material.opacity = pulse;
    line.mesh.material.emissiveIntensity = 0.4 + pulse * 0.8;
  });

  // Animate field particles along curves
  fieldParticles.forEach(fp => {
    fp.t += fp.speed * 0.008;
    if (fp.t > 1) fp.t = 0;

    const pos = fp.curve.getPoint(fp.t);
    fp.mesh.position.copy(pos);

    // Add harmonic oscillation
    const wobble = Math.sin(t * 4 + fp.t * 10) * 0.08;
    fp.mesh.position.y += wobble;
    fp.mesh.scale.setScalar(1 + Math.sin(t * 6 + fp.t * 20) * 0.3);
  });

  // Animate iron filings - magnetic attraction simulation
  const positions = filings.geometry.attributes.position.array;
  for (let i = 0; i < filingsCount; i++) {
    const ix = i * 3;
    let x = positions[ix];
    let y = positions[ix + 1];
    let z = positions[ix + 2];

    // Distance to poles
    const dxN = x + magnetRadius;
    const dyN = y + 1.8;
    const distN = Math.sqrt(dxN * dxN + dyN * dyN + z * z);

    const dxS = x - magnetRadius;
    const dyS = y + 1.8;
    const distS = Math.sqrt(dxS * dxS + dyS * dyS + z * z);

    const minDist = Math.min(distN, distS);

    // Magnetic attraction when close
    if (minDist < 4) {
      const force = (4 - minDist) * 0.02 * filingsVelocities[i].speed;
      if (distN < distS) {
        x += (dxN / distN) * force;
        y += (dyN / distN) * force;
      } else {
        x += (dxS / distS) * force;
        y += (dyS / distS) * force;
      }
    }

    // Orbit around field
    const orbitSpeed = 0.02 * filingsVelocities[i].speed;
    const cosO = Math.cos(orbitSpeed);
    const sinO = Math.sin(orbitSpeed);
    const nx = x * cosO - z * sinO;
    const nz = x * sinO + z * cosO;
    x = nx;
    z = nz;

    // Reset if captured or out of bounds
    if (y < -2.5 || minDist < 0.8 || Math.abs(x) > 10) {
      const theta = Math.random() * Math.PI * 2;
      const r = 4 + Math.random() * 4;
      x = r * Math.cos(theta);
      y = 4 + Math.random() * 3;
      z = r * Math.sin(theta);
    }

    positions[ix] = x;
    positions[ix + 1] = y;
    positions[ix + 2] = z;
  }
  filings.geometry.attributes.position.needsUpdate = true;

  // Core animation
  core.rotation.x = t * 0.5;
  core.rotation.y = t * 0.3;
  core.scale.setScalar(1 + Math.sin(t * 4) * 0.2);
  innerCore.scale.setScalar(1 + Math.sin(t * 6) * 0.15);
  innerCore.material.opacity = 0.4 + Math.sin(t * 3) * 0.2;

  controls.update();
  renderer.render(scene, camera);
}

animate();

